def distanceSumsAfterRoads(n, roads, newRoads):
    INF = 10 ** 15
    d = [[INF] * n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0
    for a, b, w in roads:
        if w < d[a][b]:
            d[a][b] = d[b][a] = w
    for k in range(n):
        dk = d[k]
        for i in range(n):
            dik = d[i][k]
            if dik < INF:
                d[i] = [x if x <= dik + y else dik + y for x, y in zip(d[i], dk)]
    out = []
    for a, b, w in newRoads:
        if w < d[a][b]:
            da = d[a][:]
            db = d[b][:]
            for i in range(n):
                x = da[i] + w
                y = db[i] + w
                row = [c if c <= x + e else x + e for c, e in zip(d[i], db)]
                d[i] = [c if c <= y + f else y + f for c, f in zip(row, da)]
        out.append(sum(sum(row) for row in d) // 2)
    return out
